\section{Setup}
Actor--critic with shared or separate networks. The full objective maximised is
\begin{equation}\label{eq:ppo-total}
  L_t^{\text{CLIP}+\text{VF}+S}(\theta) = \hat{\E}_t\left[L_t^{\text{CLIP}}(\theta) - c_1 L_t^{\text{VF}}(\theta) + c_2\, S[\pi_\theta](s_t)\right],
\end{equation}
where $L^{\text{VF}}_t = (V_\theta(s_t) - V_t^{\text{targ}})^2$ and $S$ is an entropy bonus.

Advantages use GAE \cite{schulman2016gae}:
\begin{align}
  \delta_t &= r_t + \gamma V(s_{t+1}) - V(s_t), \\
  \hat A_t &= \sum_{l=0}^{T-t-1} (\gamma\lambda)^l\, \delta_{t+l}.
\end{align}

\section{Algorithm}
\begin{algorithm}
\caption{PPO, actor--critic style}
\begin{algorithmic}
\For{iteration $= 1, 2, \dots$}
  \For{actor $= 1, \dots, N$}
    \State Run $\pi_{\theta_{\text{old}}}$ for $T$ timesteps
    \State Compute advantages $\hat A_1, \dots, \hat A_T$ \Comment{GAE}
  \EndFor
  \State Optimise \eqref{eq:ppo-total} w.r.t.\ $\theta$ with $K$ epochs and minibatch size $M \le NT$
  \State $\theta_{\text{old}} \gets \theta$
\EndFor
\end{algorithmic}
\end{algorithm}

\section{Why the clip works}
\begin{itemize}
  \item If $\hat A_t > 0$ the objective stops increasing once $r_t > 1+\epsilon$: no reward for making a good action \emph{too} much more likely.
  \item If $\hat A_t < 0$ it stops once $r_t < 1-\epsilon$.
  \item The clip only ever \emph{removes} incentives, so $L^{\text{CLIP}} \le L^{\text{CPI}}$ --- a lower bound in the spirit of conservative policy iteration.
\end{itemize}
They also try an adaptive KL penalty $\beta\,\KL[\pi_{\theta_{\text{old}}}, \pi_\theta]$; it does worse than clipping in their experiments.

\section{Practical notes}
\begin{description}
  \item[$\epsilon$] $0.2$ worked best on MuJoCo.
  \item[Implementation details] Results depend heavily on details such as advantage normalisation, value clipping, learning-rate annealing and observation normalisation\footnote{See \emph{Implementation Matters in Deep Policy Gradients} (Engstrom et al., 2020).}.
\end{description}

\begin{remark}
PPO is the optimiser behind classic RLHF (InstructGPT): the ``environment'' is a reward model, and a per-token KL penalty to the SFT policy is added to the reward.
\end{remark}

\section{Derivation}
The RLHF objective, for a reward $r$ and a reference policy $\pi_{\text{ref}}$:
\begin{equation}\label{eq:rlhf}
  \max_{\pi}\ \E_{x\sim\mathcal{D},\, y\sim\pi(\cdot\mid x)}\big[r(x,y)\big] - \beta\, \KL\big[\pi(\cdot\mid x)\,\|\,\pi_{\text{ref}}(\cdot\mid x)\big].
\end{equation}

\begin{proposition}[Closed-form optimum]\label{prop:opt}
The maximiser of \eqref{eq:rlhf} is
\[
  \pi_r(y\mid x) = \frac{1}{Z(x)}\,\pi_{\text{ref}}(y\mid x)\exp\!\Big(\tfrac{1}{\beta} r(x,y)\Big),
  \qquad Z(x) = \sum_y \pi_{\text{ref}}(y\mid x)\exp\!\Big(\tfrac{1}{\beta} r(x,y)\Big).
\]
\end{proposition}
\begin{proof}
Rewrite the objective as $-\beta\,\KL[\pi \,\|\, \pi_r] + \beta\log Z(x)$; the KL term is minimised (to $0$) at $\pi = \pi_r$.
\end{proof}

Inverting Proposition~\ref{prop:opt} expresses the reward through its optimal policy:
\begin{equation}\label{eq:reparam}
  r(x,y) = \beta \log\frac{\pi_r(y\mid x)}{\pi_{\text{ref}}(y\mid x)} + \beta\log Z(x).
\end{equation}
Under Bradley--Terry, $p(y_w \succ y_l\mid x) = \sigma\big(r(x,y_w) - r(x,y_l)\big)$, so the intractable $Z(x)$ \textbf{cancels} in the difference. Maximum likelihood over the policy gives the DPO loss.

\section{Gradient intuition}
With the implicit reward $\hat r_\theta(x,y) = \beta\log\frac{\pi_\theta(y\mid x)}{\pi_{\text{ref}}(y\mid x)}$:
\begin{align*}
\nabla_\theta \mathcal{L}_{\text{DPO}} = -\beta\,\E\Big[&\underbrace{\sigma\big(\hat r_\theta(x,y_l) - \hat r_\theta(x,y_w)\big)}_{\text{high when the implicit RM is wrong}} \\
&\cdot\big(\nabla_\theta\log\pi_\theta(y_w\mid x) - \nabla_\theta\log\pi_\theta(y_l\mid x)\big)\Big].
\end{align*}
Pairs the implicit reward model already ranks correctly get little weight. The paper shows the unweighted version makes the model degenerate.

\section{Takeaways}
\begin{itemize}
  \item ``Your language model is secretly a reward model'': any policy defines a reward via \eqref{eq:reparam}, unique up to a function of $x$.
  \item $\beta$ plays the role of the KL coefficient in PPO-based RLHF.
  \item Purely offline: it only sees the fixed preference dataset, so it cannot explore or correct for distribution shift.
\end{itemize}

\begin{idea}
Compare with IPO, KTO and online / iterative DPO. Does the offline nature hurt more on reasoning tasks?
\end{idea}

\section{Forward process}
Fixed variance schedule $\beta_1,\dots,\beta_T$ (linear from $10^{-4}$ to $0.02$, with $T = 1000$):
\[
  q(x_t \mid x_{t-1}) = \mathcal{N}\big(x_t;\ \sqrt{1-\beta_t}\,x_{t-1},\ \beta_t I\big).
\]
With $\alpha_t = 1-\beta_t$ and $\bar\alpha_t = \prod_{s\le t}\alpha_s$ we can jump to any step in closed form:
\begin{equation}\label{eq:marginal}
  q(x_t\mid x_0) = \mathcal{N}\big(x_t;\ \sqrt{\bar\alpha_t}\,x_0,\ (1-\bar\alpha_t) I\big)
  \iff x_t = \sqrt{\bar\alpha_t}\,x_0 + \sqrt{1-\bar\alpha_t}\,\epsilon,\quad \epsilon\sim\mathcal{N}(0,I).
\end{equation}

\section{Reverse process \& objective}
Learn $p_\theta(x_{t-1}\mid x_t) = \mathcal{N}(x_{t-1}; \mu_\theta(x_t,t), \sigma_t^2 I)$ with
\[
  \mu_\theta(x_t,t) = \frac{1}{\sqrt{\alpha_t}}\left(x_t - \frac{\beta_t}{\sqrt{1-\bar\alpha_t}}\,\epsilon_\theta(x_t,t)\right).
\]
Each ELBO term becomes a weighted noise-prediction error. Dropping the weights gives
\begin{equation}\label{eq:simple}
  L_{\text{simple}}(\theta) = \E_{t, x_0, \epsilon}\Big[\norm{\epsilon - \epsilon_\theta\big(\sqrt{\bar\alpha_t}x_0 + \sqrt{1-\bar\alpha_t}\,\epsilon,\ t\big)}^2\Big],
\end{equation}
which uses \eqref{eq:marginal} to sample $x_t$ directly --- no need to simulate the chain.

\section{Sampling}
\begin{algorithmic}
\State $x_T \sim \mathcal{N}(0, I)$
\For{$t = T, \dots, 1$}
  \State $z \sim \mathcal{N}(0, I)$ if $t > 1$, else $z = 0$
  \State $x_{t-1} = \frac{1}{\sqrt{\alpha_t}}\Big(x_t - \frac{1-\alpha_t}{\sqrt{1-\bar\alpha_t}}\,\epsilon_\theta(x_t, t)\Big) + \sigma_t z$
\EndFor
\State \Return $x_0$
\end{algorithmic}

