\section{Scaled dot-product attention}
\begin{equation}\label{eq:attn}
  \operatorname{Attention}(Q, K, V) = \operatorname{softmax}\!\left(\frac{QK^\top}{\sqrt{d_k}}\right) V
\end{equation}
The $1/\sqrt{d_k}$ keeps the logits at unit scale: if $q, k$ have i.i.d.\ unit-variance entries, $q^\top k$ has variance $d_k$, which would saturate the softmax.

\section{Multi-head attention}
$h$ heads attend in parallel in lower-dimensional subspaces:
\[
  \operatorname{MultiHead}(Q,K,V) = \operatorname{Concat}(\text{head}_1,\dots,\text{head}_h)\,W^O,\qquad
  \text{head}_i = \operatorname{Attention}(QW_i^Q, KW_i^K, VW_i^V).
\]

